Algorithm: INFERENCE-AWARE-SCALING (Sardana & Frankle, 2024)
Input:  Lifetime FLOP budget C_life,
        expected request volume R, avg tokens out T_bar,
        Chinchilla loss model L(N, D) = a/N^alpha + b/D^beta + L_irreducible
Output: optimal parameter count N*, training tokens D*

  // Inference-cost-per-token = 2N FLOPs (forward only)
  // Solve constrained minimization:
  //   minimize L(N, D)
  //   subject to 6 N D + 2 N R T_bar <= C_life

  Construct Lagrangian:
    Lagr(N, D, lambda) = L(N, D) + lambda*(6 N D + 2 N R T_bar - C_life)

  Solve dLagr/dN = 0, dLagr/dD = 0, dLagr/dlambda = 0 jointly.
  Under Chinchilla form, this yields the modified optimum:
    N* satisfies   alpha * a / N*^{alpha+1} = lambda * (6 D* + 2 R T_bar)
    D* satisfies   beta  * b / D*^{beta+1}  = lambda * 6 N*

  // As R grows, the inference term 2 N R T_bar dominates
  // and the optimum shifts to (smaller N, larger D)

  Return (N*, D*, lambda*)

# tp_minimal.py: torchrun --nproc_per_node=4 tp_minimal.py
import os, math, torch
import torch.distributed as dist
import torch.nn as nn

class ColumnParallelLinear(nn.Module):
    """Y = X W where W is sharded along its output (column) dim across ranks."""
    def __init__(self, in_features, out_features, world_size, rank):
        super().__init__()
        assert out_features % world_size == 0, "out_features must divide world_size"
        self.out_per_rank = out_features // world_size
        # Each rank owns a slice of the weight matrix.
        self.weight = nn.Parameter(
            torch.empty(self.out_per_rank, in_features, device="cuda")
        )
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

    def forward(self, x):
        # Input is replicated; output is sharded along columns.
        # Backward will need an all-reduce on grad_x (handled by hook below).
        return _CopyToTPRegion.apply(x) @ self.weight.t()

class RowParallelLinear(nn.Module):
    """Y = X W where W is sharded along its input (row) dim across ranks."""
    def __init__(self, in_features, out_features, world_size, rank):
        super().__init__()
        assert in_features % world_size == 0
        self.in_per_rank = in_features // world_size
        self.weight = nn.Parameter(
            torch.empty(out_features, self.in_per_rank, device="cuda")
        )
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

    def forward(self, x):
        # Input is sharded along last dim (matching col-parallel output).
        partial = x @ self.weight.t()
        # All-reduce sums partials -> full Y on every rank.
        return _AllReduceFromTPRegion.apply(partial)

# --- The f and g functions: identity / all-reduce on opposite passes. ---
class _CopyToTPRegion(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x): return x                # identity
    @staticmethod
    def backward(ctx, g):
        dist.all_reduce(g)                       # sum partial gradients
        return g

class _AllReduceFromTPRegion(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x):
        dist.all_reduce(x)                       # sum partial outputs
        return x
    @staticmethod
    def backward(ctx, g): return g               # identity

# --- A two-layer Megatron-style MLP ---
class TPMLP(nn.Module):
    def __init__(self, d, world_size, rank):
        super().__init__()
        self.up   = ColumnParallelLinear(d, 4*d, world_size, rank)
        self.down = RowParallelLinear(4*d, d, world_size, rank)
    def forward(self, x):
        return self.down(torch.nn.functional.gelu(self.up(x)))

if __name__ == "__main__":
    dist.init_process_group(backend="nccl")
    rank, world_size = dist.get_rank(), dist.get_world_size()
    torch.cuda.set_device(rank)

    mlp = TPMLP(d=4096, world_size=world_size, rank=rank)
    x = torch.randn(8, 1024, 4096, device="cuda")
    y = mlp(x)            # full y on every rank, with only one all-reduce per pass
    y.sum().backward()    # one all-reduce on grad_x

    dist.destroy_process_group()

Algorithm: Total-cost-optimal (N*, D*) accounting for inference
Input:  expected lifetime inference tokens T_inf
        Chinchilla parameters (E, A, B, alpha, beta) from Algorithm 6.3.1
        FLOPs constants: train = 6 N D, inference = 2 N per generated token
Output: (N*, D*) minimizing total FLOPs cost for target loss L_target

  // 1. Total compute = training + inference
  C_total(N, D) := 6 N D + 2 N T_inf

  // 2. Substitute D from the loss constraint L(N, D) = L_target
  //    using L(N, D) = E + A / N^alpha + B / D^beta
  D(N) := ( B / (L_target - E - A / N^alpha) )^{1 / beta}

  // 3. Minimize C_total(N, D(N)) over N
  Solve dC_total / dN = 0 numerically (one-dimensional convex problem)

  // 4. Interpretation: the optimum trades 6 D training FLOPs against 2 T_inf
  //    inference FLOPs per parameter. As T_inf grows, the optimum N* shrinks
  //    (smaller model) and D* grows (more training tokens per parameter).

  Return (N*, D*)

Practical regime (T_inf >> training tokens):
    N* ~= 0.3 to 0.5 * N*_Chinchilla   (smaller model)
    D* ~= 5 to 20 * D*_Chinchilla     (over-train on more data)
    matches Llama-3 8B (15T tokens, ~1875 tokens/param, ~94x Chinchilla)

Algorithm: HNSW SEARCH-KNN
Input:  query q, multi-layer HNSW graph H with layers L_max .. 0,
        entry point ep at layer L_max, beam width ef, return count k
Output: top-k approximate nearest neighbors of q

  // 1. Coarse descent: greedy walk on every upper layer
  current := ep
  For lc = L_max .. 1:
      current := SEARCH-LAYER-GREEDY(q, current, layer = lc)
      // greedy means: at each step move to the neighbor closer to q;
      // stop when no neighbor improves distance(q, .)

  // 2. Beam search on the dense bottom layer (layer 0)
  W := SEARCH-LAYER-BEAM(q, current, layer = 0, ef = ef)
      // maintains a min-heap of size ef ordered by distance(q, .)
      // explores neighbors of the best frontier node until no improvement

  // 3. Truncate to k
  Return k closest elements of W (by distance to q)

SEARCH-LAYER-BEAM(q, entry, layer, ef):
  visited := {entry}
  candidates := MinHeap({entry}, key = distance(q, .))      // frontier
  W         := MaxHeap({entry}, key = distance(q, .))       // top-ef so far
  While candidates is not empty:
      c := candidates.pop_min()
      if distance(q, c) > distance(q, W.peek_max()):
          break                                             // no improvement possible
      For neighbor n in graph_layer[c]:
          if n in visited: continue
          visited.add(n)
          if distance(q, n) < distance(q, W.peek_max()) or |W| < ef:
              candidates.push(n)
              W.push(n)
              if |W| > ef: W.pop_max()
  Return W

Complexity. Query time O(log N) expected on small-world graphs; per-layer hops scale
with the local degree M (typical 16..64), so total work per query is O(ef * M * log N).
